function routeBetween(root: TreeNode | null, start: number, dest: number): string {
  // adjacency: value -> list of [neighbour value, move]
  const adj = new Map<number, [number, string][]>();
  const add = (a: number, b: number, m: string) => { if (!adj.has(a)) adj.set(a, []); adj.get(a)!.push([b, m]); };
  const stack: TreeNode[] = root ? [root] : [];
  while (stack.length) {
    const node = stack.pop()!;
    for (const [child, m] of [[node.left, "L"], [node.right, "R"]] as [TreeNode | null, string][]) {
      if (!child) continue;
      add(node.val, child.val, m);
      add(child.val, node.val, "U");
      stack.push(child);
    }
  }
  const from = new Map<number, [number, string]>();
  const queue = [start];
  const seen = new Set([start]);
  for (let h = 0; h < queue.length && !seen.has(dest); h++) {
    for (const [nb, m] of adj.get(queue[h]) ?? []) {
      if (seen.has(nb)) continue;
      seen.add(nb);
      from.set(nb, [queue[h], m]);
      queue.push(nb);
    }
  }
  const moves: string[] = [];
  for (let v = dest; v !== start; v = from.get(v)![0]) moves.push(from.get(v)![1]);
  return moves.reverse().join("");
}

