function routeBetween(root: TreeNode | null, start: number, dest: number): string {
  // parent map: value -> [parent value, move from parent]
  const up = new Map<number, [number, string]>();
  const stack: TreeNode[] = root ? [root] : [];
  while (stack.length) {
    const node = stack.pop()!;
    if (node.left) { up.set(node.left.val, [node.val, "L"]); stack.push(node.left); }
    if (node.right) { up.set(node.right.val, [node.val, "R"]); stack.push(node.right); }
  }
  const pathTo = (v: number): string[] => {
    const moves: string[] = [];
    while (up.has(v)) { const [p, m] = up.get(v)!; moves.push(m); v = p; }
    return moves.reverse();
  };
  const a = pathTo(start), b = pathTo(dest);
  let k = 0;
  while (k < a.length && k < b.length && a[k] === b[k]) k++;
  return "U".repeat(a.length - k) + b.slice(k).join("");
}

